def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, qty)
    sell_book = []  # List of (price, arrival_time, id, qty)
    order_map = {}  # Maps id to (side, price, arrival_time, index_in_book)
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_map:
                side, price, arr_time, book_index = order_map[cancel_id]
                if side == 'buy':
                    if book_index < len(buy_book) and buy_book[book_index][2] == cancel_id:
                        buy_book[book_index] = (price, arr_time, cancel_id, 0)
                else:
                    if book_index < len(sell_book) and sell_book[book_index][2] == cancel_id:
                        sell_book[book_index] = (price, arr_time, cancel_id, 0)
                del order_map[cancel_id]

        elif order[0] == 'market':
            incoming_id = order[1]
            incoming_side = order[2]
            incoming_qty = order[3]

            if incoming_side == 'buy':
                incoming_qty = match_against_book(incoming_id, incoming_qty, sell_book, trades, order_map, incoming_side)
            else:
                incoming_qty = match_against_book(incoming_id, incoming_qty, buy_book, trades, order_map, incoming_side)

        elif order[0] == 'ioc':
            incoming_id = order[1]
            incoming_side = order[2]
            incoming_price = order[3]
            incoming_qty = order[4]

            if incoming_side == 'buy':
                incoming_qty = match_against_book_with_price(incoming_id, incoming_price, incoming_qty, sell_book, trades, order_map, incoming_side)
            else:
                incoming_qty = match_against_book_with_price(incoming_id, incoming_price, incoming_qty, buy_book, trades, order_map, incoming_side)

        elif order[0] == 'limit':
            incoming_id = order[1]
            incoming_side = order[2]
            incoming_price = order[3]
            incoming_qty = order[4]

            if incoming_side == 'buy':
                incoming_qty = match_against_book_with_price(incoming_id, incoming_price, incoming_qty, sell_book, trades, order_map, incoming_side)
                if incoming_qty > 0:
                    index = len(buy_book)
                    buy_book.append((incoming_price, arrival_time, incoming_id, incoming_qty))
                    order_map[incoming_id] = ('buy', incoming_price, arrival_time, index)
            else:
                incoming_qty = match_against_book_with_price(incoming_id, incoming_price, incoming_qty, buy_book, trades, order_map, incoming_side)
                if incoming_qty > 0:
                    index = len(sell_book)
                    sell_book.append((incoming_price, arrival_time, incoming_id, incoming_qty))
                    order_map[incoming_id] = ('sell', incoming_price, arrival_time, index)

    return trades

def match_against_book(incoming_id, incoming_qty, resting_book, trades, order_map, incoming_side):
    while incoming_qty > 0 and resting_book:
        resting_book.sort(key=lambda x: (x[3] > 0, x[0] if incoming_side == 'buy' else -x[0], x[1]))

        resting_price, resting_arr_time, resting_id, resting_qty = resting_book[0]

        if resting_qty == 0:
            resting_book.pop(0)
            continue

        trade_qty = min(incoming_qty, resting_qty)
        incoming_qty -= trade_qty

        resting_book[0] = (resting_price, resting_arr_time, resting_id, resting_qty - trade_qty)

        if incoming_side == 'buy':
            trades.append([incoming_id, resting_id, resting_price, trade_qty])
        else:
            trades.append([resting_id, incoming_id, resting_price, trade_qty])

        if resting_book[0][3] == 0:
            if resting_id in order_map:
                del order_map[resting_id]
            resting_book.pop(0)

    return incoming_qty

